import math

def lcm(a, b):
    return abs(a * b) // math.gcd(a, b)

def lcm_range(start, end):
    """Computes the LCM of all integers from start to end (inclusive)."""
    if start > end:
        return 1
    result = start
    for i in range(start + 1, end + 1):
        result = lcm(result, i)
    return result

def check_weakly_increasing(n, max_k):
    """
    Checks if x_{k+1} > x_k for k=1 to max_k, where
    x_k = lcm(k, k+1, ..., k+n-1).
    Returns a dictionary of results for k=1 to max_k.
    """
    results = {}
    print(f"--- Testing n = {n} ---")

    # Calculate x_1 first
    x_k_current = lcm_range(1, n)
    print(f"k=1: x_1 = {x_k_current}")

    for k in range(1, max_k):
        # Calculate x_k and x_{k+1}

        # x_k = lcm(k, k+1, ..., k+n-1)
        x_k = lcm_range(k, k + n - 1)

        # x_{k+1} = lcm(k+1, k+2, ..., k+n)
        x_k_plus_1 = lcm_range(k + 1, k + n)

        is_increasing = x_k_plus_1 > x_k

        results[k] = {
            'x_k': x_k,
            'x_k_plus_1': x_k_plus_1,
            'increasing': is_increasing
        }

        print(f"k={k}: x_{k} = {x_k}, x_{k+1} = {x_k_plus_1}. Increasing? {is_increasing}")

    return results

max_k = 5
n_values = [3, 4, 5]
all_results = {}

for n in n_values:
    all_results[n] = check_weakly_increasing(n, max_k)

print("\n--- Summary ---")
for n, results in all_results.items():
    all_increasing = all(r['increasing'] for r in results.values())
    print(f"For n={n}, is it weakly increasing for k=1..5? {all_increasing}")

